@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500&family=Playfair+Display:ital,wght@0,400;0,500;0,600;1,400;1,500&display=swap');

:root {
  --bg-color: #F5F2ED;
  --text-color: #1A1A1A;
  --accent-terracotta: #E2725B;
  --accent-sage: #8A9A86;
  --accent-sand: #D4C3A3;

  --font-serif: 'Playfair Display', serif;
  --font-sans: 'Inter', sans-serif;

  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 2rem;
  --space-lg: 4rem;
  --space-xl: 8rem;
  --space-xxl: 12rem;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-color);
  color: var(--text-color);
  font-family: var(--font-sans);
  line-height: 1.6;
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 500;
  line-height: 1.2;
}

a {
  color: inherit;
  text-decoration: none;
}

/* Header & Navigation */
header {
  padding: var(--space-md) var(--space-lg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  position: relative;
  z-index: 100;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.desktop-nav {
  display: flex;
  gap: var(--space-md);
}

.desktop-nav a {
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  transition: opacity 0.3s;
}

.desktop-nav a:hover {
  opacity: 0.6;
}

/* Mobile Menu Toggle Icon */
.mobile-nav-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  z-index: 101;
  width: 30px;
  height: 24px;
  position: relative;
}

.hamburger-line {
  display: block;
  width: 100%;
  height: 2px;
  background-color: var(--text-color);
  position: absolute;
  left: 0;
  transition: transform 0.3s ease, opacity 0.3s ease, top 0.3s ease;
}

.hamburger-line:nth-child(1) { top: 0; }
.hamburger-line:nth-child(2) { top: 11px; }
.hamburger-line:nth-child(3) { top: 22px; }

/* Active (Close) State */
.mobile-nav-toggle.active .hamburger-line:nth-child(1) {
  top: 11px;
  transform: rotate(45deg);
}
.mobile-nav-toggle.active .hamburger-line:nth-child(2) {
  opacity: 0;
}
.mobile-nav-toggle.active .hamburger-line:nth-child(3) {
  top: 11px;
  transform: rotate(-45deg);
}

/* Mobile Menu Overlay */
.mobile-menu {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background-color: var(--bg-color);
  z-index: 99;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-menu.active {
  opacity: 1;
  pointer-events: auto;
}

.mobile-menu a {
  font-family: var(--font-serif);
  font-size: 3.5rem;
  margin: var(--space-xs) 0;
  transition: opacity 0.3s;
}

.mobile-menu a:hover {
  opacity: 0.6;
}

@media (max-width: 768px) {
  header {
    padding: var(--space-md);
  }
  .desktop-nav {
    display: none;
  }
  .mobile-nav-toggle {
    display: block;
  }
}

/* Layout Utilities */
.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}
@media (max-width: 768px) {
  .container {
    padding: 0 var(--space-md);
  }
}

/* Typography specifics */
.text-lg { font-size: 1.25rem; }
.text-xl { font-size: 1.5rem; }
.text-2xl { font-size: 2rem; }
.text-3xl { font-size: 3rem; }
.text-4xl { font-size: 4rem; }
.text-5xl { font-size: 6rem; letter-spacing: -0.02em; line-height: 1; }
.text-giant { font-size: 12rem; line-height: 0.9; letter-spacing: -0.03em; }

@media (max-width: 768px) {
  .text-5xl { font-size: 3.5rem; }
  .text-giant { font-size: 5rem; }
}

/* Home */
.hero {
  padding: var(--space-xl) 0 var(--space-lg) 0;
  max-width: 1000px;
}
.hero h1 {
  margin-bottom: var(--space-md);
}

.media-showcase {
  display: grid;
  grid-template-columns: 1fr 1.5fr 1fr;
  gap: var(--space-md);
  padding: 0 var(--space-lg) var(--space-xl);
  height: 60vh;
  min-height: 400px;
}
@media (max-width: 768px) {
  .media-showcase {
    grid-template-columns: 1fr;
    height: auto;
    padding: 0 var(--space-md) var(--space-xl);
  }
  .media-showcase > div {
    height: 300px;
  }
}

.media-block {
  border-radius: 4px;
}
.block-1 { background-color: var(--accent-terracotta); }
.block-2 { background-color: var(--accent-sand); }
.block-3 { background-color: var(--accent-sage); }

/* Marquee */
.marquee-section {
  padding: var(--space-xl) 0;
  overflow: hidden;
  background-color: #EBE7E0;
}
.marquee-container {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}
.marquee-row {
  display: flex;
  white-space: nowrap;
  font-family: var(--font-serif);
  font-size: 4rem;
  font-style: italic;
  color: var(--text-color);
  opacity: 0.8;
}
.marquee-content {
  display: flex;
  width: max-content;
  animation: scroll var(--duration, 40s) linear infinite;
}
.marquee-content.reverse {
  animation-direction: reverse;
}
.marquee-row span {
  padding: 0 1rem;
}
@keyframes scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* About */
.about-section {
  padding: var(--space-xl) 0;
  max-width: 800px;
  margin: 0 auto;
}
.about-section h2 {
  font-family: var(--font-sans);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: var(--space-md);
}
.about-section p {
  font-size: 1.5rem;
  font-family: var(--font-serif);
  margin-bottom: var(--space-md);
}

/* Founder Letter (Neweno) */
.editorial-container {
  max-width: 65ch;
  margin: 0 auto;
  padding: var(--space-xl) var(--space-lg);
}
@media (max-width: 768px) {
  .editorial-container {
    padding: var(--space-lg) var(--space-md);
  }
}
.editorial-container h1 {
  margin-bottom: var(--space-xl);
  font-size: 4rem;
}
.editorial-content p {
  font-size: 1.25rem;
  margin-bottom: var(--space-md);
}

/* Services */
.services-hero {
  padding: var(--space-xl) 0 var(--space-lg);
}
.services-hero h1 {
  font-size: 4rem;
  margin-bottom: var(--space-md);
}
.philosophy {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  padding: var(--space-lg) 0 var(--space-xl);
}
@media (max-width: 768px) {
  .philosophy { grid-template-columns: 1fr; gap: var(--space-md); }
}
.philosophy h2 {
  font-size: 2.5rem;
}
.philosophy p {
  font-size: 1.25rem;
  margin-bottom: var(--space-sm);
}
.divider {
  height: 1px;
  background-color: rgba(0,0,0,0.1);
  margin: var(--space-md) 0;
}
.service-details {
  padding: var(--space-lg) 0 var(--space-xl);
}
.service-details h2 {
  font-size: 2.5rem;
  margin-bottom: var(--space-xl);
}
.service-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-xl);
}
.service-item h3 {
  font-size: 2rem;
  margin-bottom: var(--space-sm);
}
.service-item p {
  font-size: 1.25rem;
  max-width: 800px;
}

/* Clients */
.clients-hero {
  padding: var(--space-xl) 0 var(--space-md);
}
.clients-hero h1 {
  font-size: 4rem;
}
.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl) var(--space-md);
  padding: var(--space-lg) 0 var(--space-xl);
}
@media (max-width: 900px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (max-width: 600px) {
  .clients-grid {
    grid-template-columns: 1fr;
  }
}
.client-card h3 {
  font-size: 2rem;
  margin-bottom: var(--space-xs);
}
.client-card p {
  font-size: 1rem;
  opacity: 0.8;
}

/* Contact */
.contact-page {
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: var(--space-xl) var(--space-md);
}
.contact-page h1 {
  margin-bottom: var(--space-xl);
}
.contact-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}
.contact-links a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-style: italic;
  transition: opacity 0.3s;
}
.contact-links a:hover {
  opacity: 0.6;
}

document.addEventListener('DOMContentLoaded', () => {
  const toggle = document.querySelector('.mobile-nav-toggle');
  const menu = document.querySelector('.mobile-menu');

  if (toggle && menu) {
    toggle.addEventListener('click', () => {
      toggle.classList.toggle('active');
      menu.classList.toggle('active');
      document.body.style.overflow = menu.classList.contains('active') ? 'hidden' : '';
    });
  }
});

